package de.eldoria.bloodnight.generated;

import static de.eldoria.graph.std.runtime.Randoms.nextDouble;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.BukkitRuntime;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import de.eldoria.graph.std.runtime.Timer;
import io.papermc.paper.registry.RegistryKey;
import org.bukkit.Color;
import org.bukkit.Location;
import org.bukkit.Particle;
import org.bukkit.World;
import org.bukkit.entity.Creeper;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityTargetLivingEntityEvent;

public final class EnderCreeperBehaviour implements CompiledBehaviour {
    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final Particle DUST = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:dust");

    private static final TimeUnit SECONDS = TimeUnit.SECONDS;

    private static final Particle PORTAL = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:portal");

    private final MobContext context;

    private Cooldown cooldown;

    private Timer teleportTimer;

    public EnderCreeperBehaviour(MobContext context) {
        this.context = context;
        // node #44 function.cooldown
        this.cooldown = new Cooldown();
        // node #66 timer.elapsed
        this.teleportTimer = new Timer();
    }

    @Override
    public void onDamageByEntity(EntityDamageByEntityEvent event) {
        // node #10 event.damage_by_entity
        // node #14 flow.branch
        // node #11 event.damage_by_entity
        final Entity attacker = BukkitRuntime.attacker(event);
        if (attacker instanceof LivingEntity) {
            // node #13 creeper.mutate
            // node #12 cast
            final LivingEntity cast = (attacker instanceof LivingEntity ? (LivingEntity) attacker : null);
            ((Creeper) this.context.entity()).setTarget(cast);
        }
        // node #16 routine.teleport_near
        // node #15 cast
        final LivingEntity cast = (attacker instanceof LivingEntity ? (LivingEntity) attacker : null);
        teleportNear(cast);
        // node #17
    }

    @Override
    public void onDamageByPlayer(EntityDamageByEntityEvent event) {
        // node #28 event.damage_by_player
        // node #32 flow.branch
        // node #29 event.damage_by_player
        final Entity attacker = BukkitRuntime.attacker(event);
        if (attacker instanceof LivingEntity) {
            // node #31 creeper.mutate
            // node #30 cast
            final LivingEntity cast = (attacker instanceof LivingEntity ? (LivingEntity) attacker : null);
            ((Creeper) this.context.entity()).setTarget(cast);
        }
        // node #34 routine.teleport_near
        // node #33 cast
        final LivingEntity cast = (attacker instanceof LivingEntity ? (LivingEntity) attacker : null);
        teleportNear(cast);
        // node #35
    }

    @Override
    public void onTargetChange(EntityTargetLivingEntityEvent event) {
        // node #40 event.target_change
        // node #41 routine.teleport_near
        teleportNear(event.getTarget());
        // node #42
    }

    @Override
    public void onTick() {
        // node #57 mob.tick
        // node #61 flow.branch
        // node #58 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(250.0d));
        if (cooldown) {
            // node #60 world.spawn_particle
            // node #59 mob.self
            final Creeper self = ((Creeper) this.context.entity());
            BukkitRuntime.particles(this.context, self.getWorld(), DUST, self.getEyeLocation(), 5, 1.5d, 1.0d, 1.5d, new Particle.DustOptions(Color.fromRGB(128, 0, 128), 2.0f));
        }
        // node #62 routine.teleport_near
        teleportNear((((Creeper) this.context.entity()).getTarget()));
        // node #63
    }

    private void teleportNear(LivingEntity target) {
        // node #104 routine.define
        // node #119 flow.branch
        if (target == null) return;
        // node #118 flow.branch
        // node #105 timer.elapsed
        final double elapsed = this.teleportTimer.elapsed(SECONDS);
        if (!(elapsed >= 5.0d)) return;
        // node #117 flow.branch
        // node #106 mob.self
        final Creeper self = ((Creeper) this.context.entity());
        // node #107 living_entity.read
        final Location location = target.getLocation();
        if (!(self.getLocation().distance(location) > 5.0d)) return;
        // node #116 flow.branch
        // node #108 living_entity.read
        final World world = target.getWorld();
        // node #109 living_entity.read
        final double x = target.getX();
        // node #110 living_entity.read
        final double y = target.getY();
        // node #111 living_entity.read
        final double z = target.getZ();
        // node #112 location.create
        final Location location2 = new Location(world, (x + nextDouble(-2.0d, 2.0d)), (y + 0.0d), (z + nextDouble(-2.0d, 2.0d)), (float) 0, (float) 0);
        if (!(BukkitRuntime.blockAt(world, location2).isPassable() && BukkitRuntime.blockAt(world, new Location(world, (x + nextDouble(-2.0d, 2.0d)), (y + 1.0d), (z + nextDouble(-2.0d, 2.0d)), (float) 0, (float) 0)).isPassable())) return;
        // node #113 entity.teleport
        final boolean teleport = BukkitRuntime.teleport(self, location2);
        // node #114 timer.reset
        this.teleportTimer.reset();
        // node #115 world.spawn_particle
        BukkitRuntime.particles(this.context, self.getWorld(), PORTAL, location, 10, 1.5d, 1.0d, 1.5d, null);
        // node #120
    }
}
